/* @lc app=leetcode id=3443 lang=kotlin */ class Solution { fun maxDistance(s: String, k: Int): Int = s.indices.fold(Triple(0, 0, 0)) { (x, y, best), i -> (x + (if (s[i] == 'E') 1 else if (s[i] == 'W') -1 else 0)).let { nx -> (y + (if (s[i] == 'N') 1 else if (s[i] == 'S') -1 else 0)).let { ny -> Triple(nx, ny, maxOf(best, minOf(i + 1, Math.abs(nx) + Math.abs(ny) + 2 * k))) } } }.third }